  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (502::BIGINT, 'Super buena profe, tiene el material muy organizado. Te hace quiz casi que todas las semanas entonces te obliga a llevar la materia al dia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-07T00:00:00+00:00'::TIMESTAMPTZ, '07b5bda78cd3b7441cc24e5d6e631145f0d41b7f6c3a719eaadfb78ecf1f8481'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Excelente Profesora, explica claro, muy ordenada y se nota la vocación, inclusive puede formar una amistad con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c5c021741ca3fadc9976c81e1e4ee912988d89ace354cb58d7a8c0eaaa5147d7'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Muy buena profe, si usted participa en la clase es súper fácil e incluso se llega a tener una amistad con ella. Manda videos largos (nunca los vi, no es necesario) y tiene el material de clase bastante organizado. Eso si, va bastante lento entonces quizá haya que ver algunos temas muy rápido'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Brinda apoyo']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'db1c7da76e63ba6bb5a18141598ee65a2a561676126604dcd77aa4cc53cfc738'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Hace casi que un quiz por semana asi que depende de gustos de cada quien, en general buena profe'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1e2559a1e5aede0f411098fc9ae2ab94c4b792d3e5d754c3120d04ad07b57509'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La señora hace de un curso fácil algo a lo que le tenes que dedicar mucho tiempo. Su metodología es mandar videos de 2h , y en clase solo hace ejercicios y como Algebra tiene mucha teoría si no ves los videos no entendes nada porque va rapidísimo. Además califica horrible, debería tener peor nota.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '474bde7c79815f2eafd62c010d316359f674b6bb68afceefef71533ab33a2bc3'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Un amor de profe. Explica super claro, resuelve dudas de manera amable, y en general trata de crear un ambiente lindo en la clase. Es suuuper chineadora, especialmente si nota que a usted le interesa. Envia los trabajos en clase resueltos por lo que puede no ir a clase. Lleve con ella si puede.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0e5b880eb7df3a9f04eb1dbcb98f76e99363683a06a98b16f8a4877807143649'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La metodología de la profesora era difícil de seguir, explicaba con rapidez y generaba confusión. En ocasiones, sus respuestas a las preguntas de los estudiantes tenían un tono sarcástico, y se percibía cierta preferencias hacia algunos alumnos. No obstante, llegaba con entusiasmo a dar sus clases.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-12-27T00:00:00+00:00'::TIMESTAMPTZ, '5f5b4af66abc6a9be699734d43365a8339dc6a5c2ed9e66fa05bc73560734a75'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es muy buena profe 100% recomendada, hace muchos quices, pero eso ayuda para prepararse para los parciales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, '431e006dc312a70f9b9a31181c87bea2dccc751d791b51043031bfd8666689b9'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es buena profe y da buen material para el curso, pero hace quices todas las semanas casi nivel examen y es ruda calificando, casi no da puntos por procedimiento'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchos exámenes']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'a107e99dd3692cc04f29b6ef84417d6bdfac20bfb07a4aa919ac6300bae9aa16'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Una excelente profesora, su clase es muy completa, deja guías de trabajo semanales con muchos ejercicios de apoyo y videos. Califica bien los exámenes, es muy linda con los estudiantes y se nota que le apasiona enseñar, deja tareas y quices pero nada complicadas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'a549bb8765cd21c5664ff61029b8d0196ba3a5867ab199473214c38d42727b50'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Ella es una profe que toma en cuenta a sus estudiantes y siempre hace los quices tomando en cuenta las opiniones de todos. Es muy divertida y deja ejercicios extra opcionales para poder y repasar mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2024-12-04T00:00:00+00:00'::TIMESTAMPTZ, '1d693dfec5e5c09d54d418ebf02eec45fa0ca173a2447652fa2804eb143aa4b1'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Exc profe. Deja videos para ver, la mayoría son opciones. Salvo algunas semanas que tuvimos feriados. Disfruté mucho sus clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, '46c856471d4371a2fceb037f4f3f950f0efa16b33b6e5f19d16102be8c7a7f7b'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Me parece que deja muchos videos que hay que ver, si no, no entiendes la clase, a pesar de ser un curso presencial, sin embargo, es muy carismática, explica bien, es un curso bastante pesado. Algunas evaluciones son grupales'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2024-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'faf2d33790b0ab1188a93c90ee5e65aa083e9d5ba2b742bac75facf1904f67a5'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Deja muchos videos para ver fuera de clases, pero realmente se puede pasar sin verlos. Da un montón de ejercicios, aproveche para hacerlos en clase. Hace quizzes y prácticas que ayudan un montón a medirse con la materia. Ella es supercarismática y buena gente, entonces se pasa bonito.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'd2770d9faeca87f0a750044b07c613f8cc1c9bbba99db7ad1da957cc8276148c'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Es muy buena y deja todo muy claro. se preocupa por los estudiantes, eso sí hay que estar muy atento a su clase, hace muchos quices grupales entonces facilita el entendimiento. si se ven los videos que manda y se va a las clases se hace fácil pasar el examen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2024-07-18T00:00:00+00:00'::TIMESTAMPTZ, '681931536b83bdabe8e39b52c16201c8c015fb04419616671fa41e7fee42a790'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Exelente profesora, deja material muy útil para antes y después de la clase, los ejercicios vistos en clase son del nivel de un examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5d6af249b76c8a5703ebe2fb6549506e4c544f11fb3195dafeda37b80de3f77f'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Muy buena profe, aunque algo intensa. Deja mucho material "extra" para llegar preparado a la clase, lo cual ayuda en cierta parte, pero a como avance el semestre se vuelve muy tedioso. En clase la profe explica bastante bien y es amable, hace quices, portafolios y GAAPs, se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1f38594846ab85425bf1656fcd870589ba1bfd2d0c922b778eeebf370847e42d'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La materia de cada semana es autodidacta y aunque no tengo problema con eso, era demasiada y no podí abarcarla toda. Cada semana hacía quices y eran quices demasiado difíciles, al final ese rubri se ve muy afectado. Explica bien pero evalúa bien difícil'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2024-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'c1fecc03a74f0e65d5d176350ca59140d248a505caf8c82c4cb878c0fac3f6d5'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Muy linda persona, y explica excelente. Pero deja muchos videos extras, aunque la mayoria son para ver opcionales. Hace quices cada semana, aunque muchos son virtuales. Brinda muchas prácticas muy similares a las de los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '087f7b5e7f7b1b2435be811d2820fadbad7253b0929785f169d1ec5f8c0c8d37'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Es buena gente la profe, califica muy duro, hace quices difíciles todas las semanas, deja videos muy largos, medio hace un repaso de la materia y hace varios ejercicios, en modalidad semi-presencial es horrible, siempre quiere que las clases sean virtuales y técnicamente uno debe aprender solo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '84a33579dcb342735beb6f1d0ebaad0aacfca40860a3c79f00fb6a3f07f2cadc'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Un amor de profe, deja quices todas las semanas, pero no suelen ser muy complicados, la mayoría fueron virtuales, explica super bien, deja una orientación de la materia todas las semanas, pero igual antes iniciar con la resolución de los problemas, explica la materia para los que no vieron los video'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'a0130b3b181bed61cbec8c9d36d3a121ac050206236981c79a758f23b79ba713'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Es una buena profe, en clases solo resuelve ejercicios, semipresencial con ella es vacilón pero tiene sus cosillas, te prepara para los parciales. Hay evaluaciones todas las semanas y son un poco duras.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos exámenes']::TEXT[], '2023-09-01T00:00:00+00:00'::TIMESTAMPTZ, '556d11ea322173bc603958d34551b6e94b31fcd924742c02452835001e09bd2d'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Me pareció una pésima profesora, sus evaluaciones tienden a ser demasiado difíciles y en mi caso ella perdió una evaluación y me tiro la culpa de algo que es responsabilidad de ella.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-08-30T00:00:00+00:00'::TIMESTAMPTZ, '872d484ac58f1a548c882e7d37d63aca56c51ff035e644ae9c193da67cc530db'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es una muy buena profe, siempre esta atenta a dudas y consultas, sin embargo los videos que deja tienden a ser largos y además los quizes/exámenes los califica durillo; pero full la recomiendo, se aprende mucho.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases largas']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'e403957860912748bc19aca2550e213d3eba5fb2fa93d4743f538a04cabbcdd1'::TEXT, ARRAY[1034]::BIGINT[]),
    (502::BIGINT, 'Es buena profe, pero si hay que tomar en cuenta que deja consignas de los temas, y ella sólo resuelve ejercicios de práctica. No se toma el tiempo de explicar los temas desde 0, además a veces puede ser dura al calificar y hay quices todas las semanas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b7ab713efe2a44955afe5467ac40f43643e8027436034f9d4cb646687469d84e'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Un amor de profe, la quiero tanto que la consideraría mi amiga y muero por un día ir a tomar café con ella. Las clases eran súper claras y se entendía todo a la primera. De forma presencial ella deja todas las semanas una guía semanas en la que se tiene que ver un video oregrabado. Excelente opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '178c098e8f762214d0a412c21d5939a365b849cf1df99dd6fa745c280f1ae562'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'El curso se pasa fácil gracias a la profesora, es muy buena gente, explica de forma muy clara, 100% recomendada'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '374e2a846f7d4811d559c87b4bdfd23e4ba38489ab5f1b9d565d5a358c3b366c'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La profe no está súper pendiente de los estudiantes se nota que le importan. Suele dejar videos para ver antes de las clases y cuando llega a la clase se hace un repaso y se empiezan a hacer ejercicios entonces todo quede cierto súper claro. Y da mucho material para apoyarse. Recomendada????'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '349dd3b31f1bc41034d6f137ab99cd97937fd5b5ca2df8995d673496c490f259'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La profe es super buena gente y muy atenta a que de verdad uno entienda. Las explicaciones son super claras para una materia tan densa. Si puede matricule con ella'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'a37fc89a1f2ecc9f1b96cf45bb11b03f21df7860e942f8f9d58da4711de05851'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Un amor de profe, sinceramente uno se siente hasta querido con ella. Atenta a las dudas y deja mucha práctica para facilitarnos el trabajo a la hora de estudiar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '43366e79dac4abdc8a783615d66e10909bf4775c3e356b85c92d0b395955cf39'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La mejor profe que he tenido en la U hasta ahora. Excelente persona y SUPER BUENA explicando. El inicio del curso de CAL es enredado pero después del primer parcial se vuelve bonito. Con solo las clases de ella es suficiente para el examen. 100% recomendada para cualquier curso que de'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a2cd953250f66f9aa301a001c4569dc426e9fd618a232e9b8020a8e2c10bb62d'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Buena profe, deja muchos recursos para estudiar, en remoto solo daba 1 dia de clase, para que lo tomen en cuenta'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '7db032520eccdcbabd955d73df2e57a030d680c75fcc939bf8efa1c3139fbbd5'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'La profe es un amor, ayuda bastante, eso si, los revienta en quices, pero lo prepara bien para los examenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '86858508f803778ce38b20fb4ff284d1ed72ec9134fb740fc1897d8ba25bed8c'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Es segundo curso de mate que llevo con ella, apoya mucho a los estudiantes y está pendiente a resolver dudas. Se ve que ama lo que hace, si pueden matriculen con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '42cb72dc6b21eb1f29201dabe5c8d02ea92245239af28516c88d40b6034c23b5'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Muy muy buena profe, a pesar de que CDI es un curso pesado ella explica la materia de lo más bien. No dude en matricular con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '13bcbb3e01d8d5d06c17976cbb3e04bb008cd29c0bb2b668c6263b67607bc12f'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Gracias a la virtualidad llevé con la profe CDI y Calculo y algebra lineal. Y ha sido de las mejores profes que he tenido, explica muy bien y es excelente persona, recomendadisima, no van a sufris en el semestre con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '58d17ccbcdf8ca414ac18f0519b044bb6d0dc0cc6838c31ac266aca7a2802bbb'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'e6d51507045022e7e1e84b81ab44e0968786694160902750c0ef43fd2ef5b465'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Exelente profesora, explica muy bien y brinda un gran apoyo en las clases, tiene gran disponibilidad al responder consultas, llevé CDI en verano y la mayoría pasamos con buenas notas, recomendadisima espero llevar otro curso con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, '0be343b4d77e086467821e8890cb578ace6652a18a627dd789d5043d0e6cba81'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Buena profesora en virtualidad, es super ordenada. Cuando explica va directo al grano y repite las veces que sea necesario. Para un curso bastante cargado como CDI las clases no se hacen aburridas ni tediosas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '0aca83bd8160a4c266905022997f59e27c12d85ca91f51a3a69863a171ac9e00'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Natalia Es increíble para cualquier curso que tenga que llevar. Excelente opción, ella es súper ordenada, humilde y siempre dispuesta a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'f0a5c4bf9a5cdb90d23d2937f33c9400d04e9ad5725e21ad56124e6c233fc373'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es EXCELENTE. Súper ordenada, deja asignaciones (formularios ) muy sencillos , siempre está dispuesta a ayudar y explicar cuantas veces sea necesario. Sin duda una de las mejores profes de la escuela de matemática. Cien por ciento recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '963ece2b0520dabc34bbc22d412798532bf86eef06590c363f96bf1f4cfbed6a'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora. Es ordenada y brinda el material, ayuda con formularios para subir la nota ya que los quices de cátedra son algo complicados y así se repasa mucho mejor lo visto en clase, la recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'bee0cb520c0a6929ff95f4990f4e2738c960137dcca4b317d3d4b8ee49da7559'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Explica bastante bien, es muy ordenada con todo y bastante comprometida. Llevaría otro curso con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '8141f7e4b92cbc19d92d63b39371518784224d4b2da237bbf709aefcdd0db837'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora. Como muchos manifiestan, es súper ordenada y comprometida con las clases y el material que le brinda al estudiantado. Siempre se va al día con las evaluaciones y realmente se aprende. Muy recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'bf36801d816aeafa624c13e1dd84641e9fba95a1b3fe935c5ecc4c13f4da5d77'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es una profe 20/10, es muy ordenada y siempre está dispuesta a ayudar y volver a explicar si es necesario, matricule con ella, al chile es de las mejores profes que tiene el TEC'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'e57ef4f4d8b61e80d8033e8ff10210e71641177ddab22fc84e1eae06d0e015c6'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora, en modalidad virtual fue muy ordenada, da mucho apoyo en hora de consulta y las clases son muy claras. Súper recomendada'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'f2001ae8c8eb3b05820c3faa796ddd619236069106d9fa17c721f24a2fc4f036'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Buena profe, ordenada y clara explicando, se esmera en que se entiendan bien sus ejemplos y ayuda si uno lo necesita'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'adaf547715dc4e7cb7261e799607ed804b3368e852cac52a473441321180a4f2'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Buena profe'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '81fd4612ea5cfe89816758691e5c9ea8e84c11a59dbd6ac6f3da0b273d12d2e0'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Se acomodó súper bien a la modalidad virtual, fue muy ordenada. Explica muy claro, hace muchos ejemplos y es comprensiva. Llevaría otro curso con ella'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'e14b6bff9558630dfdcba5b798eaa34a0159af2af79593beadba72ffe9d82355'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '186d97a13f3e791102ccc4c56cf2323be8aa7b0136a4c0536adc760cbe0557b6'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora. En modalidad virtual una clase a la semana era sincrónica y la otra asincrónica (ambas clases las grabó) Da la clase de forma muy clara y es muy buena persona. Yo la recomiendo y volvería a llevar un curso con ella'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'e076edca6ff931924db15f1c41d6de21a94340f00df2f8111cd232c150cd5731'::TEXT, ARRAY[1641]::BIGINT[]),
    (502::BIGINT, 'Muy buena profe. Para virtual es buena opción. Una clase es sincrónica y otra asincrónica por semana pero todas las graba y las sube. Explica muy rápido pero si ve la clase grabada puede pausarla y regresarlo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'f8a97d48688138d31706f3a6fd3923373bedc924b2dc789a39a281786c31061e'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Se toma su tiempo en explicar los ejemplos para que quede bien claro. Organiza bien su clase. Tengan cuidado si le dejan una tarea o quiz para reclamar porque los suele perder, y ante casos así no es considerada, sea usted buen o mal estudiante. Pero en general, enseña bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '4c64611385153ebad11ed0c208c961845a61fce5d713a36abea4907a1191a228'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Una profe muy buena gente, ayuda a los estudiantes si tienen alguna duda y explica muy claro. Se adaptó muy bien a la modalidad virtual y las clases por zoom son muy claras.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '74cc69613c9d92ba045c1a3731f51f657bcc0858487c9e0f7785d2f1a5715d6a'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora, se adaptó a la virtualización a la perfección. Da ejemplos muy claros y en consulta siempre esta dispuesta a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '5193b8ed706440c23fdc5dfda56928a12fe30e858d3f5de36b52c0bb7134a50e'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Una profe excelente. Súper ordenada y clara a la hora de explicar. Se adaptó muy bien a las clases virtuales, definitivamente fue unos de los mejores cursos que llevé.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'b140054d2ce8d96f3836b3960ca7463993db9c5cf885616d761ce3d368438e64'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Excelente Profe, se adapto a la virtualidad a la perfección, no hubo cambio significativo entre las clases presenciales y las virtuales gracias a su manera de dar las lecciones'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'c43e820cb4b8ec1380d6f27ad12c3267b2fae5c1cbfb62f42ae049542a563673'::TEXT, ARRAY[1641]::BIGINT[]),
    (502::BIGINT, 'La profe es muy buena explicando. Se adaptó súper a la virtualidad, nos dio una clase asincrónica (pregrabada) y otra sincrónica por semana (así lo decidimos nosotros). Quices en GAAP y alguna tarea. Para los parciales lo que queda es no confiarse y practicar. El curso se logra fácil si se le pone.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '4d8a6a8ff44ec0e668cfc050673eaf53e841637976d04376b90dc70252e66ed0'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Sus explicaciones son súper claras y ordenadas. De manera virtual organizó la materia y el tiempo muy bien. Hacía quices de cada tema que servían para repasar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '9b999668811b2d83c72b681589b96958235e06d5e3ac0a78634445f676a0bf27'::TEXT, ARRAY[1641]::BIGINT[]),
    (502::BIGINT, 'Una profe excelente, ayuda bastante y las clases son muy claras'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '3046b2e66fcd119648220c1bced605ad9740acd3f0c4c5faff56b1387975abd1'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Muy buena profe, si le cuesta mate definitivamente es una excelente opción, explica clarísimo y si uno se queda atrás vuelve a explicar. Es una profe muy amigable, en general se siente que le gusta que uno aprenda. Excelente profe!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '0d7fc47d58193cc9b5f881d2840a5a9b09a38ef66aec49620313f27d4a5f56fd'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'matriculé con ella semivitual, con la pandemia todo fue virtual y la verdad es que con ella pareciera que estuvieramos en clase presencial, super clara para explicar y la clase no es tan aburrida, por lo genral deja una clase grabada y la otra la da de manera sincronica. Excelente profe'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'a2ab8429dcc03687482266c329d682e498b37fe4a95023b9fc31d0a9a2b84ffb'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Super la recomiendo para primeros ingresos. Trabaja increible con sus folletos y planes semanales. Super humilde y clara'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'a47e2cd63939791b57915223e1856b9f0565582082917fa9042e4599407e1179'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Excelente explicando, su experiencia con la modalidad semivirtual antes de la pandemia la hace manejar la virtualidad súper bien. Muy ordenada y buena gente :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'b68fccd47ac24b8ac2db446bebdd22bd9f95f3e9c4e36db48e68dfc6525e4111'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Para Álgebra, muy buena profe. Para el primer examen, se usa un folleto que ella misma hizo junto con otro profesor. Explica bien los temas y da ejemplos de lo que puede venir en el examen. Llevaría cualquier otra mate con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '47e2cbcf31a0255767b29f53cb900e6b231a10575372c863c096b5d2c7344328'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Lo más importante de resaltar es que sabe explicar MUY bien (algo que no muchos profes logran). Hace quices todas las semanas (Fáciles si se repasa). Si es ruda calificando, ya que no regala puntos si no se merecen. Si la recomiendo, es una muy buena opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'e936478817a501df80191fe026a834576ed2e64d9d49b35e18a1fdee9cbd0433'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es buena profesora, pero aveces puede ser un poco despistada, califica bastante duro. Si tiene una mejor opción váyase por esa.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'd8d45b24045fb1ac22d9702a9472ae3b64b40553d03bb378298d1552f4c77d60'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Muy buena profe, se le entiende bastante. Solo hay que tener cuidado por ella suele saltarse unos pasos que son básicos. Super recomendada. En verano da pocos ejemplos por la rapidez, así que traten de poner mucha atención. :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-12-04T00:00:00+00:00'::TIMESTAMPTZ, '1891415e1630661d48db8199a34dd2a0e9f7d93c78854d2f44163aa3f479545f'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Explica bastante bien y tiene mucha paciencia para aclarar dudas. Hace muchísimos ejemplos, es súper ordenada y si ella ve interés le va a ayudar bastante. Solo que puede que vaya muy rápido con la materia a veces.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'de0dee12c8a62f3cab0122f35ad45264e8d9f1696c329fd5cf5dd1db5211f2d0'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Buena profesora. Explica bien todos los temas durante clase. Provee material de apoyo. Muy recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'fe3e97aa0b3f6cf00351060422acef610b4cd35202089cf05741a5592faac28a'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Es una excelente profesora, hace las practicas necesarias, escribe bastante pero es lo normal del curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '35e042c13a00e468cd2e1165e50d42d30bbae37c8098c529be23d436e21afb7a'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora. Explica super claro, hace ejemplos muy similares a los del examen, muy buena gente, se interesa porque usted aprenda. Brinda exámenes viejos con solución para practicar. No dude en matricular con ella.! Es de lo mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'aaebb9306d58e19acab6bb5644be3d897101df0e72db9efbfcf9b3e16c2d9300'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Excelente'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '089c2e4d912e6602d70c3a58542b81119b195f0d53783159eebb0dfecb76b717'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'La recomiendo 100%. Califica duro, pero en clases hace bastantes ejercicios y explica muy bien. Siempre sube muchos exámenes viejos antes del parcial y si usted va a consulta también le ayuda muchísimo. Es muy buena.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '63b3ae27a32ac0aa4132705c989a30a056038b491c3f93200026fc20205ceece'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '70d2573be33af4cfdcfd9d7e073cc8e0b5f71da9a86b8e569034aaad3b1b65a3'::TEXT, ARRAY[1641]::BIGINT[]),
    (502::BIGINT, 'Sus explicaciones son muy claras, hace bastantes quices para que uno esté al día con la materia. Se interesa porque uno participe, aprenda y asista a consulta. El ambiente de clase es muy ameno también.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'c4d1e3759d29637e0b5644eaf2b14063b69037f7ac596ade52411232ccaceada'::TEXT, ARRAY[1630, 1686]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora, da muchos ejemplos y explica super claro. Califica normal y es muy accesible para hacerles consultas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-25T00:00:00+00:00'::TIMESTAMPTZ, '99b478ae1ef171e4205b62ea2c42e4599037f46dac3f9fc5f1d6d6dfd6fc831f'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Si solo le interesa pasar, recomendado. No es la mejor ni la peor'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'a6d3111bdf9780ef2a8f25d99d10ae6208c5a875fb84ab73f8a5f22396c865ab'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Es mala, muy mala y no explica nada si lleva el curso virtual ya se quedo basicamente, pasan por semestre 2 o 3 personas'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-02-07T00:00:00+00:00'::TIMESTAMPTZ, '00935720ada896fe0529e268cedbe06b70c874ff31c37cc67758ee3c3ec4f298'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '79117a61b89fca04d0154ded3603a7f07eccc327e190db499d54854c36e1b470'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Da muchos ejemplos desde sencillos hasta complicados.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c630c210024eb3b5ab9b529a86baf79dbf4efb701f63d965f34e5d7a14cde7ba'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Hace que un curso fácil se torne difícil de pasar, califica demasiado duro, hace muy pocos quices y no tiene un temperamento muy agradable que digamos. Esta encima de la asistencia de la gente y si te agarra entre ojos, suerte. No la recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8bc85e83b0174c8e32e8037fc8ee9b6ce982650f9400a831f417c82a99558fb4'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b17545db73f633656c424b5be3fceec0d80ae8e81234a766b4a35a42e72e9ff8'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8e9fe68457433483b0431ccf2a78d9a4f1a3ac48472b6328f2cab9df5f87f723'::TEXT, ARRAY[634]::BIGINT[]),
    (502::BIGINT, 'No se le entiende nada porque va muy rápido. No deja tareas por lo que no se practica fuera de clases'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-08-24T00:00:00+00:00'::TIMESTAMPTZ, '6c233d356908cd344dc6cc022b0e2b230a7b0bd898506deea07cf91b471bda47'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Buena para la materia, ayuda pero sus calificaciones son mas o menos duras.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'f7147e243dc821811da380f1940807d11f1740fe586ddb193250e4c4e3e7b270'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Explica muy bien y califica más o menos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '58d98faa4a2f65d27b1c60c3a733ba1ef3080ec18b5d6a8e68863216245971d2'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Muy buena profe da material de apoyo extra y si le pones atención el curso es fácil'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5fcedca41ccfe2032cb7995f08dea2a581cecfe9892928acd68aafc689f3bf85'::TEXT, ARRAY[1034]::BIGINT[]),
    (502::BIGINT, 'Es muy buena gente, califica normal y es bastante clara explicando, el único problema que le encontré es que los quices son rudos y para pasarlos hay que estudiar un montón, pero igual la recomiendo 100%'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9f632c6eccc0d0b212a8c96008e568939f0d57dd987208714b70af2ec91e165b'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Para este curso es muy buena, la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'dab53569a87e67b5b9e805df1bb7074549bf71d7fda20093a5954ff7b9abf443'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora. Explica muy bien y se preocupa por el estudiante. Califica normal. Quices con ejercicios de parciales de semestres pasados.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '75c8c5450159f59077302b999e27627a1394a7ac0183c74ddbf68a03800824ef'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Califica normal ,mucha práctica súper recomendada .'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '0cc399e348a6cc54cb20355070c91ab8b292ad15c48768741b395af64b106d70'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Califica duro, pero da la materia muy clara y ejercicios de un muy buen nivel, resuelve examenes antes del examen. Siempre esta dispuesta a evacuar dudas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'bc71aa136394453ed5016193793ce00aafebac91cd8eb5db64cadcbb09659b5d'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Es una profe buena dando teoría y da varios ejemplos aunque a vece suno desería ejemplos un poco más difíciles. Los quices son un poco duros si uno no lleva la materia al día. Previo a cada examen siempre resuelve de 2 a 3 parciales en clase. Califica normal.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '7b4f6790b023a7ee32bf0917596365e185e33ba90399f92c77b671c056db910e'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Califica duro y hace quices difíciles, es bastante buena explicando y deja mucha practica para llevar la materia al día'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '507efe540f69f8c3287c597c87a664bf3e7a73656e75bc95b48f240e4bf4bdeb'::TEXT, ARRAY[605]::BIGINT[]),
    (502::BIGINT, 'Para Matemática Discreta no se puede decir que sea fácil porque los exámenes son colegiados, pero explica excelente y deja mucha práctica para que uno lleve la materia al día. De verdad se preocupa para que uno aprenda, super recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-04-06T00:00:00+00:00'::TIMESTAMPTZ, '4cd2400a4be322100190395c83bdd4978b208823c3ff3cfe1daf10dc38b4eaae'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'e3afaf5a1986b36304055794c8a7f706cb02c67b225a752a765b1b8d3258fced'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Es muy buena profesora, hace muchos ejemplos con lo cual queda clara la materia, califica normal'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'fb822b9032a069d686a481e5557e004fb1fe7820898d4497497f3ea78425ad49'::TEXT, ARRAY[935]::BIGINT[]),
