    (502::BIGINT, 'Le interesa que uno realmente aprenda. Explica muy bien toda la teoría y hace muchos ejemplos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-12T00:00:00+00:00'::TIMESTAMPTZ, '566203168cdda509557dfb4d780a4d0cfd7716f9bd2e733e9d7216d2d9d3188d'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '2da3c81f5c18a734f34a77938e757883926671c98e01da0502de0c3ecead93eb'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Horrible las clases con ella, no ayuda absolutamente nadaaa. Va demasiado rápido o usted escribe o presta atencion'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'acf40f2e2d087540cb41ae6a658b578356c422365c7ea4d47bdd8479560211b0'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'La profe explica muy bien, es muy entendible, y lo prepara a uno muy bien para los examenes, deja exámenes pasados como asignaciones y hace mucha practica en clase. Si va un poco rápido, pero al final es mejor porque uno tiene tiempo para hacer examenes y entender bien la materia. Califica normal.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-26T00:00:00+00:00'::TIMESTAMPTZ, 'd98eaafb637d29913d2dc75bd39aeaec6623da0aa7567e0a2050f8e960a72ee7'::TEXT, ARRAY[935]::BIGINT[]),
    (502::BIGINT, 'Es muy buena profe, si ud lleva la meteria al día está en todas pero si no le pone se quedó.. Es excelente para alumnos responsables'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'bb643ae692ceb10067593ff03653007aae13d77ed8223805058d4402b539ee56'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Explica muy bien y deja mucha practica en clase'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'feb42cc41f313e273905f1dc860ba4ff5181085d60e6ffc207b1a08a388ff144'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'e3b0e6d3afc55adb1275f6e0084352544b90bc3e62b60b53753914fb0e25813d'::TEXT, ARRAY[1641]::BIGINT[]),
    (502::BIGINT, 'CONSEJO: prestenle TODA la atención y al final tomen foto de la materia, explica bien con varios ejemplos, pero es muy rápida para avanzar (como ya ven en los comentarios anteriores) Hace quices regulares! Es excelente, pero depende del interés de uno.. Y como digo con una foto es más sencillo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '2eb7ca2918e06ab796559c42ca292d27c6aa82475c43d9367772a1103b40181f'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '63dea6c75563559ed70a633229d40e08efb67c4fe7a0ddafb07b5ca7450d6fb3'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'PESIMA'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '915c996935f2f81941a4e041766d638c09836263cf67475d6f1b9ede135bc534'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Es muy buena profesora, el problema es que va muy rapido cuando explica, pero saca tiempo para hacer muchos ejercicios, y lo que mas me sirvió es que una o dos semanas antes de cada parcial, enviaba tres examenes para que los llevaramos hechos un dia, y se atendían dudas y hasta ella hacía varios.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1f2969bab9af3c23e6d325e92fb53db62ef0110ed1e4142a5848c738ee34a96f'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Explica muy rapido pero si uno le dice que le vuelva a explicar ella lo hace. Es buena gente. Quices muy faciles. Deja pocas tareas. No da puntos al final del curso'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8419d6eb7f12d9bf3b8471e8f2557cddbe02adcad5d9b41d5364876c79fc56eb'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Avanza muy rápido con la materia se debe decidir entre copiar o prestar atención, sin embargo se logra entender'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd12781496e6ea026fbc449fe20974123cb4a4a57dab8614ae76e8188e4dcdb4b'::TEXT, ARRAY[563, 564]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8dddcfdf407c881b903951b8d162f2ec7aad04f7bcbe6eb3630630b09efd4517'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'va muy rápido pero si le agarra ritmo entiende masomenos'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1f4ba6980421a328ac29a35ab27dcb739e65941fdece3b2d07bac3412bd4305a'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Explica sumamente rápido , o pone atención o copia , y es sumamente amargada no la recomiendo para nada no se preocupa por nadie y solo se interesa en terminar la clase'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2bfb49283ba3d407f5b26a8d973a59a2ac04b693a1ff8410f3f8ca2f49a567a6'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2e0f801d4af0985854a22791a35b70b4cdc2fa455ee1a1985bda7a11591397d2'::TEXT, ARRAY[1718, 566, 1717, 565]::BIGINT[]),
    (502::BIGINT, 'Va rapidisimo, escribes o prestas atencion asi de simple.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'eab507690290b054412aa021e80dc495fd41299c9b8f98a23a8773fbaec84680'::TEXT, ARRAY[1018]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'f5e319c28baef5cbde1cc42ecfaebd2aac53f72ff0faf1127389d0a12eb0d786'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-04T00:00:00+00:00'::TIMESTAMPTZ, '706f2d58bb2ae499fef76a636b41d653957af5ef5eb0ed526ed69c95549ab345'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Si le cuesta la matemática no lleve con ella, va muy rápido y no explica nada, si no tiene tiempo para estudiar mate no lleve con ella'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'd46f4478eaa58799fe9d7321591df9a920689543f3fa97906bd5e69139aeb352'::TEXT, ARRAY[563]::BIGINT[]),
    (502::BIGINT, 'Va demasiado rápido, se enoja si uno le pide que vuelva a explicar algo. Consulta la hace rapidísima. Nunca le entendí nada.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, '33e75dd882b5c415e9f8d6c5cadc3a702a6644e3df11750b7160cbd7c75ab5f6'::TEXT, ARRAY[2439]::BIGINT[]),
    (502::BIGINT, 'No es mala profesora, pero si tiene la desdicha de venir de un colegio donde no explicaban buena mate y lleva más de 15 créditos, posiblemente no pase. Es estricta, y va demasiado rápido, tal vez para las demás mates sea mejor opción pero para mate general ella no se toma el tiempo para que aprendas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '887aabab2fd57e77df54fb878076489f63cc94e1e4191769186518ad15b4c106'::TEXT, ARRAY[564]::BIGINT[]),
    (502::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'f5a6748285954c28798055df903e278af6ad52da0b16f2b9c1d86ca22ac685e1'::TEXT, ARRAY[634, 605]::BIGINT[]),
    (502::BIGINT, 'Excelente profesora, estricta pero amable. Si matricula con ella aprenderá un montón, pero va a tener que ponerle. Pero igual, es un amor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'a574529785c625d9e265bed0f45e64df609415ac90bacf04bd92deb55b9ff1c5'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
